package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's deterministic {@code householdId}, derived from the normalized last
 * name and postcode by {@link Households}. Because the id is a pure function of
 * (lastName, postcode), every owner with the same last name and postcode maps to the same
 * value automatically — there is no opt-in and no back-fill of existing rows. {@code
 * sharesHousehold} no longer creates the link; it only bypasses the duplicate block in
 * {@link RequireUniqueIdentity}. {@link IdentityKeys} folds the same value into an owner's
 * identity key, so the stored {@code householdId} always matches its household component.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(Households.idFor(owner.getLastName(), owner.getPostcode()));
    }
}
=== Households ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Derives the stable {@code householdId} shared by owners with the same last name and
 * postcode. The id is the {@link #hash(String) SHA-256 prefix} of the normalized last name
 * and the postcode, so every owner in the same household (same normalized last name +
 * postcode) maps to the same value automatically — no opt-in is required.
 *
 * <p>Centralising the derivation here keeps {@link AssignHousehold} (which assigns the id)
 * and {@link IdentityKeys} (which folds it into an owner's identity key) in exact agreement.
 */
public final class Households {

    private Households() {
    }

    /** The stable {@code householdId} for the given last name and postcode. */
    public static String idFor(String lastName, String postcode) {
        return hash(normalize(lastName) + "|" + (postcode == null ? "" : postcode));
    }

    /** Lower-case, trim, and collapse runs of whitespace to a single space. */
    public static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    /** Stable 12-hex-character (upper-case) prefix of the SHA-256 of the household key. */
    private static String hash(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }
}
=== AssignHouseholdSize ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code householdSize}: the number of owners sharing this owner's
 * {@code householdId} after this create, i.e. every existing member already carrying the
 * same id (back-filled by {@link AssignHousehold}) plus this owner. Runs after
 * {@link AssignHousehold} but before the owner is saved, so the new owner is counted with
 * a {@code +1}. Owners not in a shared household (null {@code householdId}) count as one.
 */
public class AssignHouseholdSize {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            owner.setHouseholdSize(1);
            return;
        }
        int count = 1; // this owner, not yet saved
        for (Owner existing : ownerRepository.findAll()) {
            if (householdId.equals(existing.getHouseholdId())) {
                count++;
            }
        }
        owner.setHouseholdSize(count);
    }
}

